  "supportive_card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19", "C43", "C49", "C51"],
  "contradictory_card_ids": ["C45", "C47", "C52", "C46", "C48", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64"],
  "prediction_basis_card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19"],
  "claims": [
    {
      "claim": "Direct nucleoside gold records provide measured oral bioavailability at or above 20% for multiple nucleoside analogs: emtricitabine 92% (C18, C28), stavudine 61-78% (C08), zidovudine 61% (C05), and didanosine 22-35% across doses and formulations (C03, C06, C07, C13, C11, C19). These are the most endpoint-direct evidence and support F >= 20% for the query as a polar ribonucleoside analog.",
      "card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19"]
    },
    {
      "claim": "L4 shows low Caco-2 permeability for the close analogs ribavirin and levovirin (C45, C47) together with high solubility (C43, C49, C51), but C47 explicitly notes that low Caco-2 permeability may reflect limited hCNT2 expression, so the assay does not affirmatively establish F < 20% in vivo.",
      "card_ids": ["C45", "C47", "C43", "C49", "C51"]
    },
    {
      "claim": "L5 gut-wall efflux and intestinal-metabolism records concern polyphenol/flavonoid glycosides and related molecules (aspalathin, kaempferol glucoside, morroniside, mulberroside A, tanshinone IIA, vitexin), not nucleosides. Their low-permeability or efflux direction does not transfer to the query and does not overturn the direct nucleoside F records.",
      "card_ids": ["C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule or its exact 5-hydroxyimidazole-4-carboxamide riboside scaffold.",
    "No permeability, nucleoside-transporter, efflux, or intestinal-metabolism data exist for the query itself; L4/L5 data are for analogs and structurally unrelated glycosides.",
    "Caco-2 permeability may underrepresent in vivo transporter-mediated absorption (C47), so low Papp is not equivalent to low F.",
    "No first-pass metabolism, systemic clearance, or formulation data are available for the query.",
    "It is unknown whether the ionized 5-hydroxy group (neutral fraction 0.04) impairs recognition by intestinal nucleoside transporters."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal-metabolism records are structurally remote from the query and do not provide affirmative F < 20% evidence for it. The most endpoint-direct evidence remains measured F >= 20% for multiple nucleoside analogs, while L4 low Caco-2 permeability for ribavirin/levovirin carries a transporter-expression caveat. Prediction remains high with low confidence."
}

